from pathlib import Path
import runpy, json, re
W=Path(__file__).parent;O=W.parent/'готовое'
helpers=runpy.run_path(str(W/'build_neuroniy_knowledge_v4_2.py'))
tree=helpers['tree'];heading=helpers['heading'];root=tree('index.html')
kb=json.loads((O/'assets/neuroniy-knowledge-v4-2.json').read_text())
kb.update(version='FIELD-winter-v4.3',updated='2026-10-09',scope='Только публичные страницы index.html, alumni.html, reviews.html. База пересобирается из HTML при выпуске сайта. Старый PDF не используется.')
docs=kb['documents']
for d in docs:
 d['kind']='event' if d['id'].startswith('event-') else 'person' if d['id'].startswith('person-') else 'faq' if d['id'].startswith('faq-') else 'review' if d['id'].startswith('review-') else 'section'
for n in root.find(lambda x:x.has('event')):
 d=next(d for d in docs if d['id']==n.attrs['id'])
 d['date']=n.find(lambda x:x.tag=='time')[0].text()
 d['host']=n.find(lambda x:x.has('event-host'))[0].text()
 d['month']=n.attrs['data-month']
 d['track']=n.attrs['data-track']
 d['guide_text']=d['guide_text'].replace('Участник эфира:','Ведущие и участники:')
for n in root.find(lambda x:x.has('person')):
 name=n.find(lambda x:x.tag=='h3')[0].text()
 d=next(d for d in docs if d['id'].startswith('person-') and name in d['text'])
 expertise=n.find(lambda x:x.has('person-expertise'))[0].text()
 role=n.find(lambda x:x.has('person-details'))[0].find(lambda x:x.tag=='p')[0].text()
 d.update(title=name,guide_text=name+'\n'+expertise+'.\n\n'+role)
for n in root.find(lambda x:x.has('faq-item')):
 title=n.find(lambda x:x.tag=='summary')[0].text()
 d=next(d for d in docs if d['id'].startswith('faq-') and d['title']==title)
 d['guide_text']=n.find(lambda x:x.tag=='p')[0].text()
for n in root.find(lambda x:x.has('week')):
 title=n.find(lambda x:x.has('week-title'))[0].text()
 body=n.find(lambda x:x.has('week-body'))[0]
 docs.append({'id':n.attrs['id'],'kind':'week','title':title,'text':n.text(),'guide_text':title+'\n\n'+body.text(),'href':'index.html#'+n.attrs['id']})
flow_aliases={
'reports':['отчёт','отчеты','таблица','сводка','аналитика','excel','презентация','документ'],
'offers':['коммерческое предложение','кп','бюджет клиента','продажи','оффер','смета'],
'knowledge':['база знаний','вторая память','obsidian','notion','заметки','библиотека','найти документ'],
'content':['smm','смм','маркетинг','контент','посты','рассылка','визуал','соцсети','бренд','стиль'],
'website':['сайт','лендинг','вайбкодинг','прототип','публикация','код','программировать'],
'automation':['автоматизация','n8n','поручение','расписание задач','рутина','бот','связать сервисы','интеграция']
}
for n in root.find(lambda x:x.has('workflow-card')):
 title=n.find(lambda x:x.tag=='h3')[0].text()
 body=n.find(lambda x:x.has('workflow-body'))[0]
 after=body.find(lambda x:x.tag=='p')[1].text().removeprefix('С ИИ ')
 route=body.find(lambda x:x.has('workflow-route'))[0]
 href=route.attrs['href']
 docs.append({'id':n.attrs['id'],'kind':'workflow','title':title,'text':n.text(),'guide_text':after+'\n\nГде в программе: '+route.text().replace(' ↗','')+'.','keywords':flow_aliases[n.attrs['id'].removeprefix('workflow-')],'href':'index.html#'+n.attrs['id'],'route':{'label':route.text().replace(' ↗',''),'href':'index.html'+href}})
archive=root.find(lambda x:x.attrs.get('id')=='archive')[0]
docs.append({'id':'archive','kind':'benefit','title':'Архив FIELD и Творческая мастерская','text':archive.text(),'guide_text':'При вступлении открываются записи всех прошлых полезных эфиров и программ сообщества FIELD и курс «Творческая мастерская». Это входит в участие; можно выбирать материалы под текущую задачу. Доступ сохраняется, пока вы в сообществе.','href':'index.html#archive'})
